///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_callAjaxSubmit_ajaxsubmit
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_callAjaxSubmit_ajaxsubmit = async function () {
    const sbmOptions = {
        id: "tx_callAjaxSubmit_ajaxsubmit",
        method: "post",
        action: "/integsrch/findKeywrd.do",
        ref: "dma_callAjaxSubmitAjaxsubmitReq",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldods20010.tx_callAjaxSubmit_ajaxsubmit" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.searchKeywrd
 * @author Inswave
 * @date 2026. 09. 29
 * @param pInput
 * @returns
 * @hidden N
*/
scwin.searchKeywrd = async function (pInput) {
    /* sdd-asis-lifecycle:begin searchKeywrd — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent('ipt_keywrdNm').setValue("");
    $c.util.getComponent('ipt_keywrdNmInput').setValue("");
    $c.util.getComponent('ipt_keywrdInit').setValue(pInput);
    $c.util.getComponent('ipt_method').setValue("findKeywrdList");
    await scwin.callAjaxSubmit();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.keyDownkeywrd
 * @author Inswave
 * @date 2026. 09. 29
 * @param event
 * @returns
 * @hidden N
*/
scwin.keyDownkeywrd = async function (event) {
    /* sdd-asis-lifecycle:begin keyDownkeywrd — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (event.keyCode == 13) {
        await scwin.callBtn();
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.callBtn
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.callBtn = async function () {
    /* sdd-asis-lifecycle:begin callBtn — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const keywrdNm = $c.util.getComponent('ipt_keywrdNmInput').getValue();
    $c.util.getComponent('ipt_keywrdNm').setValue(keywrdNm);
    $c.util.getComponent('ipt_keywrdInit').setValue("");
    scwin.removeActive();
    await scwin.callAjaxSubmit();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.callAjaxSubmit
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.callAjaxSubmit = async function () {
    /* sdd-asis-lifecycle:begin callAjaxSubmit — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    await scwin.tx_callAjaxSubmit_ajaxsubmit();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnSearchCallBack
 * @author Inswave
 * @date 2026. 09. 29
 * @param data
 * @returns
 * @hidden N
*/
scwin.fnSearchCallBack = function (data) {
    /* sdd-asis-lifecycle:begin fnSearchCallBack — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    (($c.util.getComponent('contents')) && ($c.util.getComponent('contents')).removeAll ? ($c.util.getComponent('contents')).removeAll() : (($c.util.getComponent('contents')) && ($c.util.getComponent('contents')).setValue ? ($c.util.getComponent('contents')).setValue('') : void 0)).append(data);
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.removeActive
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.removeActive = function () {
    /* sdd-asis-lifecycle:begin removeActive — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $('.sort a').removeClass('active');
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.setKeywrd
 * @author Inswave
 * @date 2026. 09. 29
 * @param keywrd
 * @returns
 * @hidden N
*/
scwin.setKeywrd = function (keywrd) {
    /* sdd-asis-lifecycle:begin setKeywrd — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $('#formatKeywrd', opener.document).val(keywrd);
    $c.win.closePopup();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.keyEvent
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.keyEvent = async function (e) {
    /* sdd-asis-lifecycle:begin keyEvent — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if ($c.util.getKeyCode(typeof e !== 'undefined' && e ? e : (typeof event !== 'undefined' ? event : undefined)) == 13 || (typeof e !== 'undefined' && e == 13)) {
        if ($c.util.getKeyCode(event) == 13) {
            try {
                await scwin.callBtn();
            } catch (e) { $c.exception.handleError(e, { notify: 'none', context: 'jldods20010' }); return; }
        }
    }
    /* sdd-asis-lifecycle:end */
};
